{
  "requirement_id": "REQ-005",
  "cases": [
    {
      "id": "TC-1",
      "title": "Allowed transitions from todo and in_progress",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"in_progress\"} on a task with status todo",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"done\"} on a task with status in_progress",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"todo\"} on a task with status in_progress"
      ],
      "expected": "允許從 todo 轉換至 in_progress，允許從 in_progress 轉換至 done，允許從 in_progress 轉換至 todo"
    },
    {
      "id": "TC-2",
      "title": "Forbidden transitions from done state",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"todo\"} on a task with status done",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"in_progress\"} on a task with status done",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"done\"} on a task with status done"
      ],
      "expected": "done 為終態，任何從 done出發的流轉均回傳 409，且任務狀態保持不變"
    },
    {
      "id": "TC-3",
      "title": "Other unlisted transitions return 409",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"done\"} on a task with status todo",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"todo\"} on a task with status todo",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"in_progress\"} on a task with status in_progress"
      ],
      "expected": "其他未列出的流轉（包含 todo 轉換至 done 以及同狀態轉換）均回傳 409"
    },
    {
      "id": "TC-4",
      "title": "Invalid status value in request returns 422",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"invalid_status\"}"
      ],
      "expected": "若請求中的 to 參數不是合法的狀態值，則回傳 422"
    }
  ]
}

